package com.blog.service.impl; import com.blog.dto.AuthDtos.*; import com.blog.entity.*; import com.blog.exception.ApiExceptions.EmailAlreadyExistsException; import com.blog.mapper.BlogMapper; import com.blog.repository.UserRepository; import com.blog.security.JwtTokenProvider; import org.junit.jupiter.api.*; import org.junit.jupiter.api.extension.ExtendWith; import org.mockito.*; import org.springframework.security.authentication.AuthenticationManager; import org.springframework.security.crypto.password.PasswordEncoder; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*;
@ExtendWith(org.mockito.junit.jupiter.MockitoExtension.class) class AuthServiceImplTest {@Mock UserRepository users;@Mock PasswordEncoder encoder;@Mock AuthenticationManager auth;@Mock JwtTokenProvider tokens;@Mock BlogMapper mapper;@InjectMocks AuthServiceImpl service;@Test void duplicateEmailFails(){when(users.existsByEmail("a@b.com")).thenReturn(true);assertThrows(EmailAlreadyExistsException.class,()->service.register(new RegisterRequest("alice","a@b.com","password1",null,null)));verify(users,never()).save(any());}@Test void registrationSavesUser(){when(encoder.encode("password1")).thenReturn("hash");when(users.save(any())).thenAnswer(i->{User u=i.getArgument(0);u.setId(1L);return u;});when(tokens.generate(any())).thenReturn("jwt");var result=service.register(new RegisterRequest("alice","a@b.com","password1",null,null));assertEquals("jwt",result.token());verify(users).save(any());}}
